#include <iostream>
using namespace std;

void swap(int* a, int* b) {
    int* temp;        // uninitialized pointer — writing to *temp is UB
    *temp = *a;       // BUG: dereferencing uninitialized pointer
    *a = *b;
    *b = *temp;       // BUG: same undefined behaviour
}

int main() {
    int x = 5, y = 10;
    swap(&x, &y);
    cout << x << " " << y << endl;
    return 0;
}

problems.fixed_code:
#include <iostream>
using namespace std;

void swap(int* a, int* b) {
    int temp = *a;    // store VALUE, not a pointer
    *a = *b;
    *b = temp;
}

int main() {
    int x = 5, y = 10;
    swap(&x, &y);
    cout << x << " " << y << endl;  // 10 5
    return 0;
}

